//! Benchmark: load time, sort time, filter time, page-fetch latency.
//!
//! Runs against synthetic Parquet files generated by `generate_datasets()`.
//!
//! Run with:
//!   cargo bench -p benchmark

use std::path::{Path, PathBuf};
use std::time::Instant;

use criterion::{criterion_group, criterion_main, BenchmarkId, Criterion, Throughput};
use polars::prelude::*;

use core::{FilterExpr, FilterValue, SortSpec, Viewport};
use query::{QueryEngine, QueryParams};
use storage::load_parquet;

// ── Synthetic data generator ──────────────────────────────────────────────────

fn generate_dataset(path: &Path, rows: usize, cols: usize) {
    if path.exists() {
        return; // reuse existing file
    }

    let mut series: Vec<Series> = Vec::with_capacity(cols);

    for c in 0..cols {
        if c == 0 {
            // Integer id column.
            let data: Vec<i64> = (0..rows as i64).collect();
            series.push(Series::new("id".into(), data));
        } else if c % 5 == 1 {
            // Float column.
            let data: Vec<f64> = (0..rows).map(|r| (r * c) as f64 * 0.001).collect();
            series.push(Series::new(format!("f_{c}").into(), data));
        } else if c % 5 == 2 {
            // String column (category-like, low cardinality).
            let cats = ["alpha", "beta", "gamma", "delta", "epsilon"];
            let data: Vec<&str> = (0..rows).map(|r| cats[r % cats.len()]).collect();
            series.push(Series::new(format!("s_{c}").into(), data));
        } else if c % 5 == 3 {
            // Boolean column.
            let data: Vec<bool> = (0..rows).map(|r| r % 2 == 0).collect();
            series.push(Series::new(format!("b_{c}").into(), data));
        } else {
            // Integer metric column.
            let data: Vec<i32> = (0..rows as i32).map(|r| r * c as i32 % 10_000).collect();
            series.push(Series::new(format!("i_{c}").into(), data));
        }
    }

    let mut df = DataFrame::new(series).expect("dataframe creation failed");

    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).ok();
    }

    let mut file = std::fs::File::create(path).expect("create parquet file");
    ParquetWriter::new(&mut file)
        .finish(&mut df)
        .expect("write parquet");

    println!(
        "Generated: {} ({} rows × {} cols, {:.1} MB)",
        path.display(),
        rows,
        cols,
        file.metadata().map(|m| m.len() as f64 / 1_048_576.0).unwrap_or(0.0)
    );
}

fn dataset_path(rows: usize, cols: usize) -> PathBuf {
    PathBuf::from(format!("benches/data/synthetic_{rows}r_{cols}c.parquet"))
}

fn ensure_datasets() {
    // Dataset A: 100k × 20
    generate_dataset(&dataset_path(100_000, 20), 100_000, 20);
    // Dataset B: 1M × 50
    generate_dataset(&dataset_path(1_000_000, 50), 1_000_000, 50);
    // Dataset C: 10M × 100 (can be slow to generate — comment out if needed)
    // generate_dataset(&dataset_path(10_000_000, 100), 10_000_000, 100);
}

// ── Benchmarks ────────────────────────────────────────────────────────────────

fn bench_load(c: &mut Criterion) {
    ensure_datasets();

    let mut group = c.benchmark_group("load_parquet");

    for (rows, cols) in &[(100_000usize, 20usize), (1_000_000, 50)] {
        let path = dataset_path(*rows, *cols);
        group.throughput(Throughput::Elements(*rows as u64));
        group.bench_with_input(
            BenchmarkId::new("rows", rows),
            &path,
            |b, path| {
                b.iter(|| {
                    load_parquet(path).expect("load failed");
                });
            },
        );
    }
    group.finish();
}

fn bench_fetch_page(c: &mut Criterion) {
    ensure_datasets();

    let mut group = c.benchmark_group("fetch_page");

    for (rows, cols) in &[(100_000usize, 20usize), (1_000_000, 50)] {
        let path = dataset_path(*rows, *cols);
        let handle = load_parquet(&path).expect("load failed");
        let engine = QueryEngine::open(&handle).expect("engine failed");

        let params = QueryParams {
            filter: FilterExpr::None,
            sort: vec![],
            viewport: Viewport::new(0, 50),
        };

        group.throughput(Throughput::Elements(50));
        group.bench_with_input(
            BenchmarkId::new("rows", rows),
            &params,
            |b, params| {
                b.iter(|| {
                    engine.fetch_page(params).expect("fetch failed");
                });
            },
        );
    }
    group.finish();
}

fn bench_sort(c: &mut Criterion) {
    ensure_datasets();

    let mut group = c.benchmark_group("sort_first_page");

    for (rows, cols) in &[(100_000usize, 20usize), (1_000_000, 50)] {
        let path = dataset_path(*rows, *cols);
        let handle = load_parquet(&path).expect("load failed");
        let engine = QueryEngine::open(&handle).expect("engine failed");

        let params = QueryParams {
            filter: FilterExpr::None,
            sort: vec![SortSpec::desc("id")],
            viewport: Viewport::new(0, 50),
        };

        group.bench_with_input(
            BenchmarkId::new("rows", rows),
            &params,
            |b, params| {
                b.iter(|| {
                    engine.fetch_page(params).expect("sort failed");
                });
            },
        );
    }
    group.finish();
}

fn bench_filter(c: &mut Criterion) {
    ensure_datasets();

    let mut group = c.benchmark_group("filter_first_page");

    for (rows, cols) in &[(100_000usize, 20usize), (1_000_000, 50)] {
        let path = dataset_path(*rows, *cols);
        let handle = load_parquet(&path).expect("load failed");
        let engine = QueryEngine::open(&handle).expect("engine failed");

        let params = QueryParams {
            filter: FilterExpr::Contains {
                column: "s_2".to_string(),
                pattern: "alpha".to_string(),
            },
            sort: vec![],
            viewport: Viewport::new(0, 50),
        };

        group.bench_with_input(
            BenchmarkId::new("rows", rows),
            &params,
            |b, params| {
                b.iter(|| {
                    engine.fetch_page(params).expect("filter failed");
                });
            },
        );
    }
    group.finish();
}

criterion_group!(benches, bench_load, bench_fetch_page, bench_sort, bench_filter);
criterion_main!(benches);
